<?php

declare(strict_types=1);

namespace ElasticKit\Index;

use ElasticKit\Index\Support\Event;
use ElasticKit\Index\Support\EventDispatcher;
use Elastic\Elasticsearch\Exception\ClientResponseException;
use RuntimeException;
use stdClass;

/**
 * Zero-downtime index rebuild: create backing index, import data, swap alias.
 *
 * $name is always the app-facing name. After rebuild, $name becomes an alias
 * pointing to a backing index generated by rebuildName().
 *
 */
class Rebuild
{
    /**
     * Lock index name.
     */
    private const LOCK_INDEX = '.ek_locks';

    /**
     * @var int
     */
    private int $batchSize = 1000;

    /**
     * @var callable|null
     */
    private $errorHandler = null;

    /**
     * @var bool
     */
    private bool $allowEmpty = false;

    /**
     * @var callable|iterable<int, array<string, mixed>>|null
     */
    private $dataSource;

    public function __construct(
        private readonly Index $index
    ) {
    }

    /**
     * Set the batch size for bulk import. Defaults to 1000.
     *
     * @param int $size
     * @return $this
     */
    public function batchSize(int $size): static
    {
        $this->batchSize = $size;
        return $this;
    }

    /**
     * Set a callback to handle bulk import errors.
     *
     * Forwards to Bulk::onError(): the callback receives the raw ES response, the
     * full batch body, and a fresh Bulk bound to the new backing index. Extract
     * the failures from $body via $response and re-import them on the Bulk, or
     * return to drop them and continue, or throw to abort (the new index is then
     * deleted). Without a handler, any import error aborts the rebuild.
     *
     * @param callable $handler function (array $response, array $body, Bulk $newbulk): void
     * @return $this
     */
    public function onError(callable $handler): static
    {
        $this->errorHandler = $handler;
        return $this;
    }

    /**
     * Allow importing zero documents without throwing. Defaults to false.
     *
     * @param bool $allow
     * @return $this
     */
    public function allowEmpty(bool $allow = true): static
    {
        $this->allowEmpty = $allow;
        return $this;
    }

    /**
     * Set a custom data source. Accepts a callable or iterable.
     * Defaults to Index::source() when not set.
     *
     * @param callable|iterable<int, array<string, mixed>> $source
     * @return $this
     */
    public function source(callable|iterable $source): static
    {
        $this->dataSource = $source;
        return $this;
    }

    /**
     * Run the rebuild: create backing index -> import data -> swap alias.
     *
     * Handles three scenarios:
     * - $name is already an alias: atomic swap (zero downtime)
     * - $name is a real index: throws RuntimeException (convert to alias mode first)
     * - $name does not exist: create alias pointing to new backing index
     *
     * The lock is always released: on failure doRun()'s exception is rethrown
     * (never masked); on success a release failure surfaces as a RuntimeException
     * noting the rebuild completed but the lock is stale. A rebuild.run.after
     * listener failure does not fail the call: run() returns normally and the
     * failure surfaces as an E_USER_WARNING.
     *
     * @param array<string, mixed> $context user-defined context passed to source()
     * @return array{newIndex: string, oldIndex: string|null}
     * @throws RuntimeException when the current alias backings carry conflicting definitions
     */
    public function run(array $context = []): array
    {
        $this->acquireLock();

        try {
            $result = $this->doRun($context);
        } catch (\Throwable $e) {
            try {
                $this->releaseLock();
            } catch (\Throwable) {
                // Ignore release failure; the original exception propagates below.
            }
            throw $e;
        }

        // Success: data is swapped, so a release failure means only the lock is stale.
        try {
            $this->releaseLock();
        } catch (\Throwable $e) {
            throw new RuntimeException(
                "Rebuild for [{$this->index->name()}] succeeded but the lock could not be released. "
                . "Data is already swapped to the new index. Call forceUnlock() to clear the stale lock.",
                0,
                $e
            );
        }

        return $result;
    }

    /**
     * Forcibly remove a stale lock left by a crashed rebuild.
     *
     * Under normal circumstances the lock is released automatically by run().
     * Call this only when a previous rebuild crashed and the lock persists.
     *
     * Idempotent: a 404 (lock index or document missing) is treated as success.
     */
    public function forceUnlock(): void
    {
        try {
            $this->index->getClient()->delete([
                'index' => self::LOCK_INDEX,
                'id' => $this->index->name(),
            ]);
        } catch (ClientResponseException $e) {
            if ($e->getResponse()->getStatusCode() !== 404) {
                throw $e;
            }
        }
    }

    /**
     * Check whether a rebuild lock is currently held for this index.
     *
     * Returns false only on a real 404; other ES errors propagate so an
     * unreachable cluster is never mistaken for an unlocked index.
     *
     * @return bool
     */
    public function isLocked(): bool
    {
        try {
            return $this->index->getClient()->exists([
                'index' => self::LOCK_INDEX,
                'id' => $this->index->name(),
            ])->asBool();
        } catch (ClientResponseException $e) {
            if ($e->getResponse()->getStatusCode() === 404) {
                return false;
            }
            throw $e;
        }
    }

    /**
     * Delete a specific backing index by name.
     *
     * @param string $indexName the backing index to delete
     */
    public function clean(string $indexName): void
    {
        $this->index->getClient()->indices()->delete([
            'index' => $indexName,
        ]);
    }

    /**
     * Rollback alias to a specific previous backing index.
     *
     * @param string $targetIndex the backing index to roll back to
     * @return string the index name that was rolled back from
     * @throws RuntimeException if alias or target index does not exist,
     *                         or the backings carry conflicting alias definitions
     */
    public function rollback(string $targetIndex): string
    {
        $name = $this->index->name();
        $client = $this->index->getClient()->indices();

        $currentResponse = $client->getAlias(['name' => $name])->asArray();
        $currentList = array_keys($currentResponse);
        if (empty($currentList)) {
            throw new RuntimeException("No index found for alias [{$name}]");
        }

        if (!$client->exists(['index' => $targetIndex])->asBool()) {
            throw new RuntimeException("Target index [{$targetIndex}] does not exist");
        }

        $definition = $this->resolveAliasDefinition($currentResponse);

        $actions = [];
        foreach ($currentList as $idx) {
            $actions[] = ['remove' => ['index' => $idx, 'alias' => $name]];
        }
        $actions[] = ['add' => ['index' => $targetIndex, 'alias' => $name] + $definition];

        $client->updateAliases([
            'body' => [
                'actions' => $actions,
            ],
        ]);

        return $currentList[0];
    }

    /**
     * Execute the rebuild logic (called after lock is acquired).
     *
     * @param array<string, mixed> $context
     * @return array{newIndex: string, oldIndex: string|null}
     */
    private function doRun(array $context): array
    {
        $name = $this->index->name();
        $client = $this->index->getClient()->indices();

        EventDispatcher::dispatch(new Event('rebuild.run.before', $name));

        // Resolved before the work: a definition conflict aborts before the import.
        $aliasExists = $client->existsAlias(['name' => $name])->asBool();
        $aliasBackings = [];
        $aliasDefinition = [];
        if ($aliasExists) {
            $aliasResponse = $client->getAlias(['name' => $name])->asArray();
            $aliasBackings = array_keys($aliasResponse);
            $aliasDefinition = $this->resolveAliasDefinition($aliasResponse);
        }

        $newIndex = $this->createIndex();

        try {
            $this->import($newIndex, $context);
        } catch (\Throwable $e) {
            // Import precedes every alias write, so the new index is always a safe orphan.
            $this->deleteQuietly($newIndex);
            throw $e;
        }

        $oldIndex = null;

        try {
            $client->refresh(['index' => $newIndex]);

            if ($aliasExists) {
                $oldIndex = $aliasBackings[0] ?? null;
                $actions = [];
                foreach ($aliasBackings as $idx) {
                    $actions[] = ['remove' => ['index' => $idx, 'alias' => $name]];
                }
                $actions[] = ['add' => ['index' => $newIndex, 'alias' => $name] + $aliasDefinition];
                $client->updateAliases(['body' => ['actions' => $actions]]);
            } elseif ($client->exists(['index' => $name])->asBool()) {
                throw new RuntimeException(
                    "Index [{$name}] is a real index, not an alias. "
                    . "Rebuild requires an alias to swap atomically. "
                    . "Delete the index manually or convert it to alias mode before running rebuild."
                );
            } else {
                $client->putAlias(['index' => $newIndex, 'name' => $name]);
            }
        } catch (\Throwable $e) {
            // A lost response can leave the swap applied — never delete an index
            // the alias may already point to; keep it when in doubt.
            $swapped = $this->aliasPointsTo($name, $newIndex);

            if ($swapped === true) {
                throw new RuntimeException(sprintf(
                    'Rebuild for [%s]: the swap failed, but alias [%s] already points to [%s] '
                    . '(updateAliases may have been applied before the failure). '
                    . 'The new index was kept. Inspect the cluster, then rollback() or clean() manually.',
                    $name,
                    $name,
                    $newIndex
                ), 0, $e);
            }

            if ($swapped === null) {
                throw new RuntimeException(sprintf(
                    'Rebuild for [%s]: the swap failed and the alias state could not be verified. '
                    . 'The new index [%s] was kept to avoid deleting possibly live data. '
                    . 'Inspect the cluster, then rollback() or clean() manually.',
                    $name,
                    $newIndex
                ), 0, $e);
            }

            // Alias verifiably does not point to the new index — a safe orphan.
            $this->deleteQuietly($newIndex);
            throw $e;
        }

        // The swap is committed — an exception here would read as a failed rebuild (rollback).
        $event = new Event('rebuild.run.after', $name);
        $event->newIndex = $newIndex;
        $event->oldIndex = $oldIndex;
        try {
            EventDispatcher::dispatch($event);
        } catch (\Throwable $e) {
            trigger_error(sprintf(
                'Rebuild for [%s] succeeded — alias [%s] now points to [%s] (%s) — '
                . 'but a rebuild.run.after listener failed (%s: %s). The rebuild result stands.',
                $name,
                $name,
                $newIndex,
                $oldIndex !== null ? "replacing [{$oldIndex}]" : 'no previous backing index',
                $e::class,
                $e->getMessage()
            ), E_USER_WARNING);
        }

        return ['newIndex' => $newIndex, 'oldIndex' => $oldIndex];
    }

    /**
     * Whether $alias currently resolves to $index.
     *
     * True/false when the alias state is verifiable (false includes "alias
     * does not exist"); null when it cannot be verified (non-404 failure).
     */
    private function aliasPointsTo(string $alias, string $index): ?bool
    {
        try {
            $backing = array_keys(
                $this->index->getClient()->indices()->getAlias(['name' => $alias])->asArray()
            );
        } catch (ClientResponseException $e) {
            return $e->getResponse()->getStatusCode() === 404 ? false : null;
        } catch (\Throwable) {
            return null;
        }

        return in_array($index, $backing, true);
    }

    /**
     * The alias definition (filter, routing, is_write_index) a new backing
     * inherits from the alias's current backings. is_write_index is excluded
     * from the conflict check: only one backing may hold it, so asymmetry is
     * a legal state.
     *
     * @param array<string, mixed> $response a getAlias response body
     * @return array<string, mixed>
     * @throws RuntimeException when the backings carry conflicting definitions
     */
    private function resolveAliasDefinition(array $response): array
    {
        $name = $this->index->name();
        $definitions = [];
        $hasWriteIndex = false;
        foreach ($response as $backing => $entry) {
            $definition = $entry['aliases'][$name] ?? [];
            $hasWriteIndex = $hasWriteIndex || !empty($definition['is_write_index']);
            unset($definition['is_write_index']);
            $definitions[$backing] = $definition;
        }

        $first = null;
        $firstBacking = null;
        foreach ($definitions as $backing => $definition) {
            if ($first === null) {
                $first = $definition;
                $firstBacking = $backing;
                continue;
            }
            // loose ==: key order must not read as a conflict
            if ($definition != $first) {
                throw new RuntimeException(sprintf(
                    'Alias [%s] backs indexes with different definitions: [%s => %s, %s => %s]. '
                    . 'A rebuild collapses the backings into one index and cannot carry both. '
                    . 'Align the definitions or split the alias, then re-run.',
                    $name,
                    $firstBacking,
                    json_encode($first) ?: '',
                    $backing,
                    json_encode($definition) ?: ''
                ));
            }
        }

        if ($first === null) {
            return [];
        }
        if ($hasWriteIndex) {
            $first['is_write_index'] = true;
        }
        return $first;
    }

    /**
     * Best-effort cleanup delete; a failure here must not mask the exception
     * being handled. A leftover backing index is removable via clean().
     */
    private function deleteQuietly(string $index): void
    {
        try {
            $this->index->getClient()->indices()->delete(['index' => $index]);
        } catch (\Throwable) {
            // Swallow: the original failure is what the caller needs to see.
        }
    }

    /**
     * Acquire the distributed lock using ES document create (op_type=create).
     *
     * @throws RuntimeException if the lock is already held
     */
    private function acquireLock(): void
    {
        $this->ensureLockIndex();

        $name = $this->index->name();

        try {
            $this->index->getClient()->index([
                'index' => self::LOCK_INDEX,
                'id' => $name,
                'body' => ['locked_at' => date(\DateTimeInterface::ATOM)],
                'op_type' => 'create',
            ]);
        } catch (ClientResponseException $e) {
            if ($e->getResponse()->getStatusCode() === 409) {
                throw new RuntimeException(
                    "Rebuild for [{$name}] is already running. "
                    . "Call forceUnlock() if the previous rebuild crashed."
                );
            }
            throw $e;
        }
    }

    /**
     * Release the lock. Idempotent: only 404 is swallowed; other failures
     * (transport, 5xx) propagate so a stale lock stays detectable.
     *
     * @throws ClientResponseException for any non-404 failure
     */
    private function releaseLock(): void
    {
        try {
            $this->index->getClient()->delete([
                'index' => self::LOCK_INDEX,
                'id' => $this->index->name(),
            ]);
        } catch (ClientResponseException $e) {
            if ($e->getResponse()->getStatusCode() === 404) {
                return; // Lock already gone — idempotent
            }
            throw $e;
        }
    }

    /**
     * Ensure the lock index exists. Handles concurrent creation races.
     */
    private function ensureLockIndex(): void
    {
        $indices = $this->index->getClient()->indices();

        if ($indices->exists(['index' => self::LOCK_INDEX])->asBool()) {
            return;
        }

        try {
            $indices->create([
                'index' => self::LOCK_INDEX,
                'body' => [
                    'settings' => [
                        'number_of_shards' => 1,
                        'number_of_replicas' => 0,
                        'index.hidden' => true,
                    ],
                ],
            ]);
        } catch (ClientResponseException $e) {
            // Race: another process may have created it concurrently
            if ($indices->exists(['index' => self::LOCK_INDEX])->asBool()) {
                return;
            }
            throw $e;
        }
    }

    /**
     * Create a new backing index using mappings/settings from the Index subclass.
     *
     * @return string the new backing index name
     */
    protected function createIndex(): string
    {
        $newIndex = $this->index->rebuildName();
        $mappings = $this->index->mappings();
        $settings = $this->index->settings();

        $this->index->getClient()->indices()->create([
            'index' => $newIndex,
            'body' => [
                'mappings' => empty($mappings) ? new stdClass() : $mappings,
                'settings' => empty($settings) ? new stdClass() : $settings,
            ],
        ]);

        return $newIndex;
    }

    /**
     * Import data into the target index.
     *
     * @param string $newIndex
     * @param array<string, mixed> $context
     */
    protected function import(string $newIndex, array $context): void
    {
        if ($this->dataSource !== null) {
            $items = is_callable($this->dataSource) ? ($this->dataSource)($context) : $this->dataSource;
        } else {
            $items = $this->index->source($context);
        }

        $bulk = (new Bulk($this->index))->target($newIndex)->batchSize($this->batchSize);
        if ($this->errorHandler) {
            $bulk->onError($this->errorHandler);
        }

        $count = 0;
        foreach ($items as $id => $doc) {
            if (!is_array($doc)) {
                throw new RuntimeException(
                    "source() must yield [id => document] pairs, got non-array value for key [{$id}]. "
                    . "Expected: yield \$id => ['field' => 'value'], got \$id => " . gettype($doc)
                );
            }
            $bulk->index($id, $doc);
            $count++;
        }

        if ($count === 0 && !$this->allowEmpty) {
            throw new RuntimeException(
                "Rebuild imported 0 documents for index [{$newIndex}]. "
                . "Call allowEmpty() if this is intentional."
            );
        }

        $bulk->flush();
    }
}
